// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.25;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/utils/structs/EnumerableMap.sol";

import {CoreLib} from "./CoreLib.sol";
import {HookLib} from "./HookLib.sol";
import {Operator} from "./Operator.sol";
import {CommonUtils} from "../utils/CommonUtils.sol";

import "../interfaces/Errors.sol";
import "../interfaces/Constants.sol";
import "../interfaces/IDSS.sol";
import "../interfaces/IKarakBaseVault.sol";
import "../interfaces/Events.sol";

library SlasherLib {
    using Operator for Operator.State;
    using EnumerableMap for EnumerableMap.AddressToUintMap;
    using CommonUtils for address[];

    struct SlashRequest {
        address operator;
        uint96[] slashPercentagesWad;
        address[] vaults;
    }

    struct QueuedSlashing {
        IDSS dss;
        uint96 timestamp;
        address operator;
        address[] vaults;
        uint256[] earmarkedStakes;
        uint256 nonce;
    }

    function calculateRoot(QueuedSlashing memory queuedSlashing) internal pure returns (bytes32 root) {
        root = keccak256(abi.encode(queuedSlashing));
    }

    function validateVaultsAndSlashPercentages(
        CoreLib.Storage storage self,
        SlashRequest memory slashingRequest,
        IDSS dss
    ) internal view {
        if (slashingRequest.vaults.hasDuplicates()) revert DuplicateSlashingVaults();

        uint256 maxSlashPercentageWad = getDSSMaxSlashablePercentageWad(self, dss);
        for (uint256 i = 0; i < slashingRequest.vaults.length; i++) {
            if (!self.operatorState[slashingRequest.operator].isVaultStakeToDSS(dss, slashingRequest.vaults[i])) {
                revert VaultNotStakedToDSS();
            }
            if (slashingRequest.slashPercentagesWad[i] == 0) revert ZeroSlashPercentageWad();
            if (slashingRequest.slashPercentagesWad[i] > maxSlashPercentageWad) revert MaxSlashPercentageWadBreached();
        }
    }

    function validateRequestSlashingParams(CoreLib.Storage storage self, SlashRequest memory slashingRequest, IDSS dss)
        internal
        view
    {
        // revert if slashing cooldown has not passed
        if (block.timestamp < self.operatorState[slashingRequest.operator].nextSlashableTimestamp[dss]) {
            revert SlashingCooldownNotPassed();
        }
        // vaults length and corresponding slashPercentages array length should match
        if (slashingRequest.slashPercentagesWad.length != slashingRequest.vaults.length) revert LengthsDontMatch();
        // Max vaults slashed per request
        if (slashingRequest.vaults.length > Constants.MAX_SLASHABLE_VAULTS_PER_REQUEST) {
            revert MaxSlashableVaultsPerRequestBreached();
        }
        // Non zero vault length check
        if (slashingRequest.vaults.length == 0) revert EmptyArray();
        // Validate vault addresses and slashPercentages Values
        validateVaultsAndSlashPercentages(self, slashingRequest, dss);
    }

    function fetchEarmarkedStakes(SlashRequest memory slashingMetadata)
        internal
        view
        returns (uint256[] memory earmarkedStakes)
    {
        earmarkedStakes = new uint256[](slashingMetadata.vaults.length);
        for (uint256 i = 0; i < slashingMetadata.vaults.length; ++i) {
            earmarkedStakes[i] = Math.mulDiv(
                slashingMetadata.slashPercentagesWad[i],
                IKarakBaseVault(slashingMetadata.vaults[i]).totalAssets(),
                Constants.MAX_SLASHING_PERCENT_WAD
            );
        }
    }

    function requestSlashing(
        CoreLib.Storage storage self,
        IDSS dss,
        SlashRequest memory slashingMetadata,
        uint256 nonce
    ) external returns (QueuedSlashing memory queuedSlashing) {
        validateRequestSlashingParams(self, slashingMetadata, dss);
        uint256[] memory earmarkedStakes = fetchEarmarkedStakes(slashingMetadata);
        queuedSlashing = QueuedSlashing({
            dss: dss,
            timestamp: uint96(block.timestamp),
            operator: slashingMetadata.operator,
            vaults: slashingMetadata.vaults,
            earmarkedStakes: earmarkedStakes,
            nonce: nonce
        });
        self.slashingRequests[calculateRoot(queuedSlashing)] = true;
        self.operatorState[slashingMetadata.operator].nextSlashableTimestamp[dss] =
            block.timestamp + Constants.SLASHING_COOLDOWN;
        HookLib.callHookIfInterfaceImplemented({
            dss: dss,
            data: abi.encodeWithSelector(
                dss.requestSlashingHook.selector, slashingMetadata.operator, slashingMetadata.slashPercentagesWad
            ),
            interfaceId: dss.requestSlashingHook.selector,
            ignoreFailure: true,
            hookCallGasLimit: self.hookCallGasLimit,
            supportsInterfaceGasLimit: self.supportsInterfaceGasLimit,
            hookGasBuffer: self.hookGasBuffer
        });
    }

    function finalizeSlashing(CoreLib.Storage storage self, QueuedSlashing memory queuedSlashing) external {
        bytes32 slashRoot = calculateRoot(queuedSlashing);
        if (!self.slashingRequests[slashRoot]) revert InvalidSlashingParams();
        if (queuedSlashing.timestamp + Constants.SLASHING_VETO_WINDOW > block.timestamp) {
            revert MinSlashingDelayNotPassed();
        }
        delete self.slashingRequests[slashRoot];

        for (uint256 i = 0; i < queuedSlashing.vaults.length; i++) {
            IKarakBaseVault(queuedSlashing.vaults[i]).slashAssets(
                queuedSlashing.earmarkedStakes[i],
                self.assetSlashingHandlers[IKarakBaseVault(queuedSlashing.vaults[i]).asset()]
            );
        }
        IDSS dss = queuedSlashing.dss;

        HookLib.callHookIfInterfaceImplemented({
            dss: dss,
            data: abi.encodeWithSelector(dss.finishSlashingHook.selector, queuedSlashing.operator),
            interfaceId: dss.finishSlashingHook.selector,
            ignoreFailure: true,
            hookCallGasLimit: self.hookCallGasLimit,
            supportsInterfaceGasLimit: self.supportsInterfaceGasLimit,
            hookGasBuffer: self.hookGasBuffer
        });
    }

    function cancelSlashing(CoreLib.Storage storage self, QueuedSlashing memory queuedSlashing) external {
        bytes32 slashRoot = calculateRoot(queuedSlashing);
        if (!self.slashingRequests[slashRoot]) revert InvalidSlashingParams();
        delete self.slashingRequests[slashRoot];
        IDSS dss = queuedSlashing.dss;

        HookLib.callHookIfInterfaceImplemented({
            dss: dss,
            data: abi.encodeWithSelector(dss.cancelSlashingHook.selector, queuedSlashing.operator),
            interfaceId: dss.cancelSlashingHook.selector,
            ignoreFailure: true,
            hookCallGasLimit: self.hookCallGasLimit,
            supportsInterfaceGasLimit: self.supportsInterfaceGasLimit,
            hookGasBuffer: self.hookGasBuffer
        });
    }

    function getDSSMaxSlashablePercentageWad(CoreLib.Storage storage self, IDSS dss) public view returns (uint256) {
        return self.dssMaxSlashablePercentageWad[dss];
    }

    function setDSSMaxSlashablePercentageWad(
        CoreLib.Storage storage self,
        IDSS dss,
        uint256 dssMaxSlashablePercentageWad
    ) public {
        uint256 currentSlashablePercentageWad = self.dssMaxSlashablePercentageWad[dss];
        if (currentSlashablePercentageWad != 0) revert DSSAlreadyRegistered();
        if (dssMaxSlashablePercentageWad == 0) revert ZeroSlashPercentageWad();
        if (dssMaxSlashablePercentageWad > Constants.MAX_SLASHING_PERCENT_WAD) revert MaxSlashPercentageWadBreached();
        self.dssMaxSlashablePercentageWad[dss] = dssMaxSlashablePercentageWad;
    }
}

d19a4de35bcaf31ccec8bccd36e2d26594d05aad.src/entities/NativeVaultLib.sol:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.25;

import {LibClone} from "solady/src/utils/LibClone.sol";

import "./VaultLib.sol";
import "../interfaces/Errors.sol";
import "../interfaces/Events.sol";
import "../interfaces/Constants.sol";
import "../interfaces/INativeNode.sol";

import "../entities/BeaconProofsLib.sol";

library NativeVaultLib {
    enum ValidatorStatus {
        INACTIVE,
        ACTIVE,
        WITHDRAWN
    }

    struct ValidatorDetails {
        // index of the validator
        uint40 validatorIndex;
        // status is set to ACTIVE when withdraw credential proof is submitted
        ValidatorStatus status;
        // amount of ETH restaked from beacon chain
        uint256 restakedBalanceWei;
        // timestamp of validator's last balance update
        uint64 lastBalanceUpdateTimestamp;
    }

    struct Snapshot {
        // node balance without awarded shares
        uint256 nodeBalanceWei;
        // change in balance for all validators
        int256 balanceDeltaWei;
        // number of proofs to submit for finalizing the snapshot
        uint256 remainingProofs;
        // beacon block root corresponding to block.number - 1
        bytes32 parentBeaconBlockRoot;
    }

    struct NativeNode {
        // CREATE2 address of the node
        address nodeAddress;
        // total restaked ETH (beacon + node balance)
        uint256 totalRestakedETH;
        // withdrawable ETH with shares awarded
        uint256 withdrawableCreditedNodeETH;
        // current snapshot details
        Snapshot currentSnapshot;
        // timestamp of last finalized snapshot
        uint64 lastSnapshotTimestamp;
        // total validators with withdrawal credentials pointed to this node
        uint256 activeValidatorCount;
        // timestamp of ongoing snapshot, 0 if no ongoing snapshot
        uint64 currentSnapshotTimestamp;
        // validator details keyed from its public key hash
        mapping(bytes32 => ValidatorDetails) validatorPubkeyHashToDetails;
    }

    struct QueuedWithdrawal {
        // receiver's address
        address to;
        // timestamp when withdraw was started
        uint96 start;
        // assets (ETH) to be withdrawn
        uint256 assets;
        // owner of the NativeNode being withdrawn from
        address nodeOwner;
    }

    /// @custom:storage-location erc7201:native-vault.storage
    struct Storage {
        // node implementation address
        address nodeImpl;
        // virtual assets for 4626 vault
        uint256 totalAssets;
        // store for sending slashed assets to
        address slashStore;
        // mapping of native node to its owner
        mapping(address => address) nodeToOwner;
        // mapping of owners to details of their native node
        mapping(address => NativeNode) ownerToNode;
        // mapping of node owner to their withdraw nonce
        mapping(address nodeOwner => uint256 withdrawNonce) nodeOwnerToWithdrawNonce;
        // mapping of node owner to their total pending withdrawal amount
        mapping(address nodeOwner => uint256 withdrawAmount) nodeOwnerToWithdrawAmount;
        // mapping of owners' withdraw nonce to pending withdrawals
        mapping(bytes32 ownerWithdrawNonce => QueuedWithdrawal withdrawal) withdrawalMap;
    }

    function deployNode(Storage storage self, VaultLib.Config storage config, address owner)
        internal
        returns (address)
    {
        bytes32 salt = keccak256(abi.encodePacked(config.operator, owner));

        INativeNode newNode = INativeNode(address(LibClone.deployDeterministicERC1967BeaconProxy(address(this), salt)));
        newNode.initialize(address(this), owner);

        emit NodeDeployed(msg.sender, address(newNode), self.nodeImpl);
        return address(newNode);
    }

    function calculateWithdrawKey(address nodeOwner, uint256 nodeOwnerNonce) internal pure returns (bytes32) {
        return keccak256(abi.encode(nodeOwner, nodeOwnerNonce));
    }

    function validateSnapshotProof(
        Storage storage self,
        address nodeOwner,
        ValidatorDetails memory validatorDetails,
        bytes32 balanceRoot,
        BeaconProofs.BalanceProof calldata proof
    ) internal returns (int256 balanceDeltaWei) {
        address nodeAddress = self.ownerToNode[nodeOwner].nodeAddress;
        uint64 timestamp = self.ownerToNode[nodeOwner].currentSnapshotTimestamp;

        uint40 validatorIndex = validatorDetails.validatorIndex;
        uint256 prevBalanceWei = validatorDetails.restakedBalanceWei;
        uint256 newBalanceWei = BeaconProofs.validateBalance(balanceRoot, validatorIndex, proof);

        validatorDetails.restakedBalanceWei = newBalanceWei;
        validatorDetails.lastBalanceUpdateTimestamp = timestamp;

        if (newBalanceWei == 0) {
            self.ownerToNode[nodeOwner].activeValidatorCount--;
            validatorDetails.status = ValidatorStatus.WITHDRAWN;

            emit ValidatorWithdrawn(nodeOwner, nodeAddress, timestamp, validatorIndex);
        }
        self.ownerToNode[nodeOwner].validatorPubkeyHashToDetails[proof.pubkeyHash] = validatorDetails;

        emit SnapshotValidator(nodeOwner, nodeAddress, timestamp, validatorIndex);

        if (newBalanceWei != prevBalanceWei) {
            emit ValidatorBalanceChanged(nodeOwner, nodeAddress, validatorIndex, timestamp, newBalanceWei);

            balanceDeltaWei = int256(newBalanceWei) - int256(prevBalanceWei);
        }

        return balanceDeltaWei;
    }

    function validateWithdrawalCredentials(
        Storage storage self,
        address nodeOwner,
        uint64 updateTimestamp,
        bytes32 beaconStateRoot,
        BeaconProofs.ValidatorFieldsProof calldata validatorFieldsProof
    ) internal returns (uint256) {
        bytes32 validatorPubkeyHash = BeaconProofs.getPubkeyHash(validatorFieldsProof.validatorFields);
        NativeVaultLib.ValidatorDetails memory validatorDetails =
            self.ownerToNode[nodeOwner].validatorPubkeyHashToDetails[validatorPubkeyHash];

        if (validatorDetails.status != NativeVaultLib.ValidatorStatus.INACTIVE) revert ValidatorAlreadyActive();
        if (BeaconProofs.getExitEpoch(validatorFieldsProof.validatorFields) != type(uint64).max) {
            revert ValidatorExiting();
        }
        // Construct beacon chain withdraw address with current node's payable address
        if (
            BeaconProofs.getWithdrawalCredentials(validatorFieldsProof.validatorFields)
                != bytes32(abi.encodePacked(bytes1(uint8(1)), bytes11(0), address(self.ownerToNode[nodeOwner].nodeAddress)))
        ) {
            revert WithdrawalCredentialsMismatchWithNode();
        }

        uint256 restakedBalanceWei = BeaconProofs.getEffectiveBalanceWei(validatorFieldsProof.validatorFields);
        BeaconProofs.validateValidatorProof(
            validatorFieldsProof.validatorProof.validatorIndex,
            validatorFieldsProof.validatorFields,
            validatorFieldsProof.validatorProof.proof,
            beaconStateRoot
        );

        validatorDetails.status = NativeVaultLib.ValidatorStatus.ACTIVE;
        validatorDetails.validatorIndex = validatorFieldsProof.validatorProof.validatorIndex;
        validatorDetails.lastBalanceUpdateTimestamp = updateTimestamp;
        validatorDetails.restakedBalanceWei = restakedBalanceWei;
        self.ownerToNode[nodeOwner].validatorPubkeyHashToDetails[validatorPubkeyHash] = validatorDetails;
        self.ownerToNode[nodeOwner].activeValidatorCount++;

        emit RestakedValidator(
            nodeOwner,
            self.ownerToNode[nodeOwner].nodeAddress,
            validatorFieldsProof.validatorProof.validatorIndex,
            updateTimestamp,
            restakedBalanceWei
        );
        return restakedBalanceWei;
    }
}

